<script setup lang="ts">
import { ref } from 'vue';
import { onShow } from '@dcloudio/uni-app';
import type { Shelf, ShelfTheme } from '../../../types';
import { dataService } from '../../../services/data';

const themes: { value: ShelfTheme; label: string }[] = [{ value: 'SAGE', label: '鼠尾草' },{ value: 'AMBER', label: '琥珀' },{ value: 'SKY', label: '雾蓝' },{ value: 'ROSE', label: '浅粉' },{ value: 'GRAPHITE', label: '石墨' }];
const shelves = ref<Shelf[]>([]); const showForm = ref(false); const editingId = ref(''); const name = ref(''); const themeIndex = ref(0); const loadError = ref('');
async function load() { shelves.value = []; loadError.value = ''; try { shelves.value = await dataService.shelves(); } catch (error) { loadError.value = error instanceof Error ? error.message : '展示架加载失败'; } }
function add() { showForm.value = true; editingId.value = ''; name.value = ''; themeIndex.value = 0; }
function edit(shelf: Shelf) { const index = themes.findIndex((theme) => theme.value === shelf.theme); if (index < 0) return void uni.showToast({ title: '展示架主题无效', icon: 'none' }); showForm.value = true; editingId.value = shelf.id; name.value = shelf.name; themeIndex.value = index; }
async function save() { const normalized = name.value.trim(); if (!normalized) return void uni.showToast({ title: '请填写展示架名称', icon: 'none' }); try { const data = { name: normalized, theme: themes[themeIndex.value]!.value }; if (editingId.value) await dataService.updateShelf(editingId.value, data); else await dataService.createShelf(data); showForm.value = false; await load(); } catch (error) { uni.showToast({ title: error instanceof Error ? error.message : '保存失败', icon: 'none' }); } }
async function move(index: number, direction: number) { const target = index + direction; if (target < 0 || target >= shelves.value.length) return; const next = [...shelves.value]; const [entry] = next.splice(index, 1); if (!entry) return; next.splice(target, 0, entry); try { shelves.value = await dataService.reorderShelves(next.map((shelf) => shelf.id)); } catch (error) { uni.showToast({ title: error instanceof Error ? error.message : '排序失败', icon: 'none' }); } }
function remove(shelf: Shelf) { if (shelf.itemCount > 0) return void uni.showToast({ title: '展示架中仍有收藏，无法删除', icon: 'none' }); uni.showModal({ title: `删除“${shelf.name}”？`, content: '仅删除这个空展示架。', confirmText: '删除', confirmColor: '#9d3d36', success: async (result) => { if (!result.confirm) return; try { await dataService.removeShelf(shelf.id); await load(); } catch (error) { uni.showToast({ title: error instanceof Error ? error.message : '删除失败', icon: 'none' }); } } }); }
onShow(() => void load());
</script>

<template>
  <view class="page shelves-page"><view class="header"><text class="eyebrow">ORGANIZE</text><text class="display-title">展示架</text><button class="primary-button" @tap="add">＋ 新建展示架</button></view>
    <view v-if="loadError" class="load-error">{{ loadError }}</view><view v-else class="shelf-list"><view v-for="(shelf,index) in shelves" :key="shelf.id" class="shelf-card card"><view class="swatch" :class="`swatch--${shelf.theme}`" /><view class="shelf-copy"><strong>{{ shelf.name }}</strong><text>{{ shelf.itemCount }} 件</text></view><view class="shelf-actions"><button @tap="move(index,-1)">↑</button><button @tap="move(index,1)">↓</button><button @tap="edit(shelf)">编辑</button><button class="delete" @tap="remove(shelf)">删除</button></view></view></view>
    <view v-if="showForm" class="backdrop" @tap="showForm = false" /><view v-if="showForm" class="sheet"><text class="section-title">{{ editingId ? '编辑展示架' : '新建展示架' }}</text><text class="form-label">名称</text><input v-model="name" class="form-input" maxlength="30" placeholder="例如：城市纸袋" /><text class="form-label">颜色</text><picker :range="themes" range-key="label" :value="themeIndex" @change="themeIndex = Number($event.detail.value)"><view class="form-picker">{{ themes[themeIndex]?.label }}</view></picker><view class="sheet-actions"><button class="secondary-button" @tap="showForm = false">取消</button><button class="primary-button" @tap="save">保存</button></view></view>
  </view>
</template>

<style scoped>
.header { margin: 18rpx 0 38rpx; }.header .display-title { display: block; margin: 10rpx 0 34rpx; font-size: 60rpx; }.load-error { padding: 24rpx; border-radius: 20rpx; background: #fae2de; color: #943d37; font-size: 24rpx; }.shelf-list { display: grid; gap: 18rpx; }.shelf-card { display: grid; grid-template-columns: 28rpx 1fr auto; gap: 20rpx; align-items: center; padding: 24rpx; }.swatch { height: 92rpx; border-radius: 999rpx; background: #75a88d; }.swatch--AMBER { background: #f09a2a; }.swatch--SKY { background: #229ee8; }.swatch--ROSE { background: #fd53c0; }.swatch--GRAPHITE { background: #585c63; }.shelf-copy strong,.shelf-copy text { display: block; }.shelf-copy strong { font-size: 28rpx; }.shelf-copy text { margin-top: 7rpx; color: #7e766c; font-size: 21rpx; }.shelf-actions { display: flex; gap: 7rpx; }.shelf-actions button { min-width: 52rpx; margin: 0; padding: 10rpx 12rpx; border-radius: 12rpx; background: #ece5da; color: #4e4942; font-size: 20rpx; line-height: 1.2; }.shelf-actions .delete { color: #963f39; background: #fae7e3; }.backdrop { position: fixed; z-index: 80; inset: 0; background: rgba(26,23,20,.42); }.sheet { position: fixed; z-index: 81; left: 0; right: 0; bottom: 0; padding: 48rpx 32rpx calc(env(safe-area-inset-bottom) + 32rpx); border-radius: 40rpx 40rpx 0 0; background: #f8f4ec; box-shadow: 0 -20rpx 60rpx rgba(30,24,18,.18); }.sheet-actions { display: grid; grid-template-columns: 1fr 1.4fr; gap: 16rpx; margin-top: 36rpx; }
</style>
